    if(R()<.22&&SP.mishaps.length){ const m=pick(SP.mishaps); L.push(["ann",f(m.text,x)]); perf-=1.3; if(!moment) moment=f(m.memory,x); }
    else L.push(["ann",f(pick(perf>=0?cls.good:cls.bad),x)]);
