    L.push(["ann",f(P(SP.scores),{...x,j1:s.judges[0].name,j2:s.judges[1].name,j3:s.judges[2].name,s1:spNum(sc[0]),s2:spNum(sc[1]),s3:spNum(sc[2]),t:spNum(tot)})]);
