  if(lv===0){ if(epic&&c.i===0&&c.sec==="intro") FI.braam(b,t,ch[0],c.bs*1.6,.7*epic); if(last&&c.sec==="intro"){ D.riser(b,t+c.bs*.4,c.bs*.6); } return; }
