  if(epic){
    if(lv>=2){ const hit=sub===3?[0,3]:beats===3?[0,2,3]:[0,3,4,6,7]; hit.forEach((k,j)=>FI.drum(b,t+k*s,(j===0?1:.6)*epic,j%2?62:50)); }
    if(lv>=2){ for(let k=0;k<n*2;k++) PI.pulse(b,t+k*s/2,ch[0]-12,s*.42,.5*epic); }
    if(c.i===0&&lv>=3){ FI.impact(b,t,epic); FI.braam(b,t,ch[0],c.bs*1.4,epic); }
    else if(c.i===0&&lv===2) FI.braam(b,t,ch[0],c.bs,.6*epic);
  }
  if(c.i===0&&lv>=3&&!epic&&(pop||goth)) FI.impact(b,t,.5);
