  if(last&&c.sec!=="outro"){ D.riser(b,t+c.bs*.45,c.bs*.55); const k0=Math.floor(n/2); for(let k=k0;k<n;k++) for(const h of [0,.5]) D.snare(b,t+(k+h)*s,.12+.4*(k-k0)/(n-k0),.15,1); }
